package dev.rux.plugins.deviceinfo

import android.content.Context
import android.os.BatteryManager
import android.os.Build
import dev.rux.generated.rux_device_info.Battery
import dev.rux.generated.rux_device_info.BatteryState
import dev.rux.generated.rux_device_info.DeviceInfo
import dev.rux.generated.rux_device_info.DeviceInfoApi

/**
 * Android implementation of `DeviceInfoApi` (the interface is generated by `rux build` from
 * the plugin's Rust declaration). Registered by `[package.metadata.rux.native]`.
 */
class DeviceInfoApiImpl(private val context: Context) : DeviceInfoApi {
    override fun info() = DeviceInfo(
        platform = "Android",
        osVersion = "${Build.VERSION.RELEASE} (API ${Build.VERSION.SDK_INT})",
        model = "${Build.MANUFACTURER} ${Build.MODEL}",
        isSimulator = Build.FINGERPRINT.contains("generic") || Build.HARDWARE == "ranchu",
    )

    override fun battery(callback: (Result<Battery>) -> Unit) {
        // Async: answer from a background thread (the reply is delivered on the UI thread).
        Thread {
            val manager = context.getSystemService(BatteryManager::class.java)
            val level = manager?.getIntProperty(BatteryManager.BATTERY_PROPERTY_CAPACITY)
                ?.takeIf { it in 0..100 }
            val state = when (manager?.getIntProperty(BatteryManager.BATTERY_PROPERTY_STATUS)) {
                BatteryManager.BATTERY_STATUS_CHARGING -> BatteryState.CHARGING
                BatteryManager.BATTERY_STATUS_DISCHARGING,
                BatteryManager.BATTERY_STATUS_NOT_CHARGING -> BatteryState.DISCHARGING
                BatteryManager.BATTERY_STATUS_FULL -> BatteryState.FULL
                else -> BatteryState.UNKNOWN
            }
            callback(Result.success(Battery(level, state)))
        }.start()
    }
}
